# C:\\Users\\Administrator\\Documents\\CodeProject\\headfile\\UnifyNetSDK\\gen_ctypes_file\\_3_replace\\HK_NetSDK.h: 22884
def MAKE_RESOLUTION(_interlace_, _width_, _height_, _fps_):
    return (
        ((_interlace_ << 28) | (((_width_ >> 3) & 0x1FF) << 19))
        | (((_height_ >> 1) & 0x7FF) << 8)
    ) | (_fps_ & 0xFF)


# C:\\Users\\Administrator\\Documents\\CodeProject\\headfile\\UnifyNetSDK\\gen_ctypes_file\\_3_replace\\HK_NetSDK.h: 22888
def GET_RES_INTERLACE(_res_):
    return (_res_ >> 28) & 0x1


# C:\\Users\\Administrator\\Documents\\CodeProject\\headfile\\UnifyNetSDK\\gen_ctypes_file\\_3_replace\\HK_NetSDK.h: 22890
def GET_RES_WIDTH(_res_):
    return ((_res_ >> 19) & 0x1FF) << 3


# C:\\Users\\Administrator\\Documents\\CodeProject\\headfile\\UnifyNetSDK\\gen_ctypes_file\\_3_replace\\HK_NetSDK.h: 22892
def GET_RES_HEIGHT(_res_):
    return ((_res_ >> 8) & 0x7FF) << 1


# C:\\Users\\Administrator\\Documents\\CodeProject\\headfile\\UnifyNetSDK\\gen_ctypes_file\\_3_replace\\HK_NetSDK.h: 22894
def GET_RES_FPS(_res_):
    return _res_ & 0xFF


